//! Typed errors carrying a Spark error class and SQLSTATE (ADR 0008, 0029).
//!
//! The registry is generated by `build.rs` from `spark-error-conditions.json`
//! (Spark 4.2.0's `error-conditions.json`, vendored verbatim) plus
//! `krishiv-error-classes.json`. Spark classes copy Spark's name, SQLSTATE and
//! message template; Krishiv-only classes are prefixed `KRISHIV_`. The whole
//! Spark catalog is data; the classes the engine actually raises are the ones
//! referenced from engine code (see `cargo xtask registry-coverage`).
//!
//! Each class has a generated parameter struct, so a missing or extra
//! message parameter is a compile error:
//!
//! ```
//! use krishiv_common::error::{DivideByZero, ErrorClass, KrishivError};
//!
//! let e = KrishivError::from(DivideByZero { config: "\"spark.sql.ansi.enabled\"".into() });
//! assert_eq!(e.error_class(), ErrorClass::DivideByZero);
//! assert_eq!(e.sql_state(), Some("22012"));
//! ```
//!
//! ```compile_fail
//! // Missing parameter `config`.
//! let _ = krishiv_common::error::DivideByZero {};
//! ```
//!
//! ```compile_fail
//! // Extra parameter `hint`.
//! let _ = krishiv_common::error::DivideByZero { config: String::new(), hint: String::new() };
//! ```

#[cfg_attr(
    not(test),
    expect(
        dead_code,
        reason = "`placeholders` is used by build.rs and tests only"
    )
)]
mod template;

mod render;
pub use render::render_with_context;

include!(concat!(env!("OUT_DIR"), "/error_classes.rs"));

use std::sync::Arc;

/// How an error's query context arose: a span of SQL text, or a
/// DataFrame operation (Spark's `QueryContextType`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ErrorContextType {
    /// A span of SQL text.
    Sql,
    /// A DataFrame operation.
    DataFrame,
}

/// Where an error arose, as Spark's `QueryContext`: the fragment of SQL
/// text (with `start`/`stop` byte offsets, `stop` inclusive) or the
/// DataFrame operation that raised it. `object_type`/`object_name` name
/// the object (a view, usually empty), `call_site` the user code that
/// raised it (empty: the engine does not track call sites yet) and
/// `summary` a short description.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ErrorQueryContext {
    /// Whether this context is a SQL span or a DataFrame operation.
    pub context_type: ErrorContextType,
    /// The redacted SQL fragment (empty for DataFrame contexts).
    pub fragment: String,
    /// First byte of the span (0 for DataFrame contexts).
    pub start: usize,
    /// Last byte of the span, inclusive (0 for DataFrame contexts).
    pub stop: usize,
    /// The object type (`""` when the error is directly in the query).
    pub object_type: String,
    /// The object name (`""` when the error is directly in the query).
    pub object_name: String,
    /// The user code that raised the error (empty: not tracked yet).
    pub call_site: String,
    /// A short description of the error's cause.
    pub summary: String,
}

impl ErrorQueryContext {
    /// A SQL context: the redacted `fragment` at bytes `start..=stop`.
    #[must_use]
    pub fn sql(fragment: impl Into<String>, start: usize, stop: usize) -> Self {
        Self {
            context_type: ErrorContextType::Sql,
            fragment: fragment.into(),
            start,
            stop,
            object_type: String::new(),
            object_name: String::new(),
            call_site: String::new(),
            summary: String::new(),
        }
    }

    /// A DataFrame context (the engine does not track call sites yet).
    #[must_use]
    pub fn dataframe() -> Self {
        Self {
            context_type: ErrorContextType::DataFrame,
            fragment: String::new(),
            start: 0,
            stop: 0,
            object_type: String::new(),
            object_name: String::new(),
            call_site: String::new(),
            summary: String::new(),
        }
    }
}

/// An error with a Spark error class, SQLSTATE and message parameters.
///
/// `Display` matches Spark 4's `getMessage` without query context:
/// `[ERROR_CLASS] message SQLSTATE: xxxxx` (no suffix for the Spark classes
/// that have no SQLSTATE). Like Spark, every `_LEGACY_ERROR_*` class omits
/// the `[ERROR_CLASS]` prefix.
///
/// An error may have a classified cause, as a Spark exception has a Java
/// cause: Spark wraps a reader failure as `FAILED_READ_FILE.NO_HINT` caused
/// by the specific condition. [`Self::cause`] and
/// [`std::error::Error::source`] expose it; like Spark's `getMessage`,
/// `Display` leaves it out.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("{}{message}{}", class_prefix(*class), sql_state_suffix(*class))]
pub struct KrishivError {
    class: ErrorClass,
    parameters: Vec<(&'static str, String)>,
    message: String,
    #[source]
    cause: Option<Arc<KrishivError>>,
    contexts: Vec<ErrorQueryContext>,
}

fn class_prefix(class: ErrorClass) -> String {
    if class.name().starts_with("_LEGACY_ERROR_") {
        String::new()
    } else {
        format!("[{}] ", class.name())
    }
}

fn sql_state_suffix(class: ErrorClass) -> String {
    class
        .sql_state()
        .map_or_else(String::new, |s| format!(" SQLSTATE: {s}"))
}

impl KrishivError {
    /// Builds an error; callers outside this module go through the generated
    /// parameter structs, which guarantee `parameters` match the template.
    fn from_parts(class: ErrorClass, parameters: Vec<(&'static str, String)>) -> Self {
        let message = template::render(class.message_template(), &parameters);
        Self {
            class,
            parameters,
            message,
            cause: None,
            contexts: Vec::new(),
        }
    }

    /// The same error caused by `cause` (replacing any earlier cause).
    #[must_use]
    pub fn with_cause(mut self, cause: KrishivError) -> Self {
        self.cause = Some(Arc::new(cause));
        self
    }

    /// The direct cause, if any; [`Self::causes`] walks the whole chain.
    pub fn cause(&self) -> Option<&KrishivError> {
        self.cause.as_deref()
    }

    /// The causes, nearest first (not including `self`).
    pub fn causes(&self) -> impl Iterator<Item = &KrishivError> {
        std::iter::successors(self.cause(), |e| e.cause())
    }

    /// The error class.
    pub fn error_class(&self) -> ErrorClass {
        self.class
    }

    /// The SQLSTATE of the error class, if Spark defines one.
    pub fn sql_state(&self) -> Option<&'static str> {
        self.class.sql_state()
    }

    /// The rendered message, without the `[CLASS]` prefix or SQLSTATE suffix.
    pub fn message(&self) -> &str {
        &self.message
    }

    /// Message parameters as `(spark_name, value)`, in template order.
    pub fn message_parameters(&self) -> &[(&'static str, String)] {
        &self.parameters
    }

    /// This error with `context` attached (where it arose, as Spark's
    /// query context); replaces no context already attached.
    #[must_use]
    pub fn with_query_context(mut self, context: ErrorQueryContext) -> Self {
        self.contexts.push(context);
        self
    }

    /// The attached query contexts, oldest first (empty when the error
    /// carries none, e.g. an execution error like division by zero).
    pub fn query_contexts(&self) -> &[ErrorQueryContext] {
        &self.contexts
    }

    /// The same error with every message parameter replaced by
    /// [`crate::secret::REDACTED`], for an error raised at a secret (a
    /// syntax error at a password in query text). Its causes are redacted
    /// the same way.
    #[must_use]
    pub fn redacted(&self) -> Self {
        let parameters = self
            .parameters
            .iter()
            .map(|(k, _)| (*k, crate::secret::REDACTED.to_owned()))
            .collect();
        let mut out = Self::from_parts(self.class, parameters);
        out.cause = self.cause.as_ref().map(|c| Arc::new(c.redacted()));
        out.contexts = self.contexts.clone();
        out
    }
}

/// Renders the error-class reference as Markdown (`cargo xtask docs-errors`).
pub fn docs_markdown() -> String {
    let mut out = String::from(
        "# Krishiv error classes\n\n\
         <!-- @generated by `cargo xtask docs-errors` from the error-class JSON files; do not edit. -->\n\n\
         | Error class | SQLSTATE | Message template |\n\
         |---|---|---|\n",
    );
    for c in ErrorClass::ALL {
        let template = c
            .message_template()
            .replace('&', "&amp;")
            .replace('<', "&lt;")
            .replace('>', "&gt;")
            .replace('|', "\\|")
            .replace('\n', "<br>");
        out.push_str(&format!(
            "| `{}` | `{}` | {} |\n",
            c.name(),
            c.sql_state().unwrap_or("-"),
            template.trim_end()
        ));
    }
    out
}

